impl<T: RetireOwned> RetirementCursor for UnorderedSet<T> {
    fn close_step(&mut self,_:usize)->RetirementStep {self.0.next().map_or(RetirementStep::Complete,|value|RetirementStep::Child(value.retirement()))}
